6.463974,-15.254483],[-56.464172,-15.254547],[-56.464277,-15.254558],[-56.464392,-15.254642],[-56.464461,-15.254736],[-56.464516,-15.254835]],[[-56.374124,-15.191076],[-56.374133,-15.191229],[-56.374135,-15.191345],[-56.374143,-15.191447],[-56.374161,-15.191697],[-56.374184,-15.191938],[-56.374186,-15.192216]],[[-56.373205,-15.189501],[-56.373282,-15.189568],[-56.373344,-15.189641],[-56.373542,-15.189951],[-56.373698,-15.190246],[-56.373805,-15.190438],[-56.37387,-15.190526],[-56.373948,-15.190611],[-56.373998,-15.190693]],[[-56.336344,-15.14277],[-56.336416,-15.142829],[-56.336563,-15.142937],[-56.337254,-15.143265]]]}$q$), 4326), $q${"regra_id":"mt_010_246_p061_2021_rosario_oeste_acorizal_26t","orgao":"SINFRA-MT","uf":"MT","rodovia":"MT-010/MT-246","nome":"MT-010 (Rosário Oeste – Entr. MT-246, Acorizal) e MT-246 (Entr. BR-163/364 – Entr. MT-010), incisos I e III","resumo":"restrito (só com AET, dia útil) veículo com PBT a partir de 26 t, mais de 3 eixos e mais de 14 m de comprimento","criterio":{"caminhoes":true,"peso_igual_ou_acima_t":26,"eixos_acima":3,"comprimento_acima_m":14,"cumulativo":true},"horario":"AET; sem horário fixo, dias úteis; proibido sábado a partir das 13h, domingo e feriado mesmo com AET","ato":"Portaria SINFRA 061/2021/GS/SINFRA-MT, arts. 1º (I e III), 2º e 3º (I) (DOE-MT 28.107 de 20/10/2021, p. 28)","ato_url":"https://www.normasbrasil.com.br/norma/portaria-61-2021-mt_421943.html","publicacao":"2021-10-20","texto":"Art. 1º Fica restrito o trânsito de Veículos de Carga, CVC, CTV e de cargas indivisíveis com Peso Bruto Total - PBT, cheio ou vazio, igual ou superior a 26.000 (vinte e seis mil) kg, com mais de 3 (três) eixos e comprimento acima de 14,00 (quatorze) metros, nas rodovias e trechos mencionados a seguir: I - Rodovia MT 010, trecho compreendido entre o limite do perímetro urbano do Município de Rosário Oeste e o entroncamento com a Rodovia MT 246 - Acorizal; ... III - Rodovia MT 246, trecho compreendido entre o entroncamento com a BR 163/364 e o entroncamento com a Rodovia MT 010. Art. 3º I - para as Rodovias MT 010 e MT 246, não haverá restrição de horário, sendo, todavia, o trânsito permitido nos dias úteis e proibido, mesmo com AET, aos sábados, a partir de 13 horas, aos domingos e feriados.","status":"vigente","ativa":true,"confianca":"media","verificacao":"Texto da portaria (DOE-MT de 20/10/2021, lido no IOMAT e no Normas Brasil) conferido em 18/10/2026; revoga a Portaria 041/2021 (art. 5º); nenhuma revogação/alteração posterior localizada (a Portaria 010/2023 não a cita). Os limites unidos por vírgula e \"e\" são lidos como cumulativos. Geometria: segmentos SRE 010EEMT0100/0095/0090 e 246EEMT0070/0065/0063/0062 (GeoDados-MT) casados com o OSM, extensões batem com o SRE (40,9 e 20,4 km).","excecoes":"Passa quem tem AET (art. 2º: carga/descarga às margens, domicílio no trecho ou obra de manutenção), em dia útil; sábado a partir das 13h, domingo e feriado é proibido mesmo com AET. O inciso II (MT-010 do entroncamento com a MT-246 ao km 4+600, Rodoanel/BR-163) e o inciso IV (MT-251, Estrada-Parque) ficam sem geometria.","fonte_geometria":"trecho localizado no OSM (ways com ref MT-010 e MT-246) entre as pontas dos segmentos SRE do GeoDados-MT","geometria_info":{"extensao_km":61.275,"trechos":[{"metodo":"ways do OSM com ref MT-010","ways_ref":450,"ancoras":[{"nome":"Início do PU de Rosário Oeste","lon":-56.421224,"lat":-14.829109,"dist_ancora_m":4},{"nome":"Entr. MT-246(B) (acesso a Acorizal)","lon":-56.336287,"lat":-15.142964,"dist_ancora_m":28}],"extensao_km":40.862,"extensao_ato_km":40.9,"pistas_paralelas":1},{"metodo":"ways do OSM com ref MT-246","ways_ref":94,"ancoras":[{"nome":"Entr. BR-163/364","lon":-56.464088,"lat":-15.255,"dist_ancora_m":3},{"nome":"Entr. MT-010(B)","lon":-56.336287,"lat":-15.142964,"dist_ancora_m":28}],"extensao_km":20.413,"extensao_ato_km":20.4,"pistas_paralelas":4}]}}$q$::jsonb, null::timestamptz, null::timestamptz)
